package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import java.io.*;import java.time.*;import java.util.*;import static org.junit.Assert.*;
/** Actual editor/review/cancel/Save with private plans, SQLite and fake scheduling only. */
public final class GoalAlarmTimeFlowTest {
 final SunriseTimeFlowTest ui=new SunriseTimeFlowTest();final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();SleepPlans.Factory oldPlans;String preferences;Application app;Application.ActivityLifecycleCallbacks observer;
 interface Work{void run(AlarmSkipFixture f)throws Exception;}
 void plan(int bedtime,int goal){SleepPlan p=SleepPlans.load(c);p.bedtime=bedtime;p.goal=goal;p.wake=(bedtime+goal)%1440;SleepPlans.save(c,p);}
 void capture(String name)throws Exception{ui.frame();assertTrue(ui.d.takeScreenshot(new File(ui.folder(),"goal-alarm-"+name+".png")));}
 void run(Work work)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",ui.d.executeShellCommand("getprop ro.kernel.qemu").trim());oldPlans=SleepPlans.factory;preferences="goal-alarm-ui-"+UUID.randomUUID();SleepPlans.factory=context->c.getSharedPreferences(preferences,0);app=(Application)c.getApplicationContext();observer=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertTrue(a instanceof AlarmEditorActivity||a instanceof GoalAlarmTimeActivity);ui.owned.add(a);}public void onActivityResumed(Activity a){ui.current=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(observer);try(AlarmSkipFixture f=new AlarmSkipFixture()){try{work.run(f);}catch(Exception|AssertionError error){try{ui.d.takeScreenshot(new File(ui.folder(),"goal-alarm-failure.png"));ui.d.dumpWindowHierarchy(new File(ui.folder(),"goal-alarm-failure.xml"));}catch(Exception diagnostic){error.addSuppressed(diagnostic);}throw error;}finally{ui.i.runOnMainSync(()->{for(Activity a:ui.owned)if(!a.isDestroyed())a.finish();});ui.await("goal alarm owners closed",()->ui.owned.stream().allMatch(Activity::isDestroyed));}}finally{app.unregisterActivityLifecycleCallbacks(observer);SleepPlans.factory=oldPlans;c.deleteSharedPreferences(preferences);}}
 void save()throws Exception{Activity owner=ui.current;ui.click("Save alarm");ui.await("saved editor closed",owner::isDestroyed);}
 @Test public void missingInvalidStaleCancelDraftRecreationSaveAndReopenRequireExplicitApplication()throws Exception{run(f->{Alarm initial=f.load();initial.enabled=false;initial.extraLoud=true;initial.sunrise=true;initial.tone="pulse";initial.volume=55;try(Store s=f.open()){s.save(initial);}String before=initial.json().toString();ui.launch(initial);ui.click("Use sleep plan");ui.shown("Sleep plan alarm error");capture("missing");ui.click("Cancel");ui.shown("Edit alarm");assertEquals(before,f.load().json().toString());assertEquals(0,f.schedules);c.getSharedPreferences(preferences,0).edit().putInt("goal",15).putInt("bedtime",1390).commit();ui.click("Use sleep plan");ui.shown("Sleep plan alarm error");capture("invalid");ui.click("Cancel");plan(1390,450);ui.click("Use sleep plan");ui.shown("Plan-derived alarm time");capture("review");ui.recreate("Plan-derived alarm time");capture("recreated");plan(1400,450);ui.click("Use fixed time");ui.shown("Saved plan or time zone changed. Refresh the proposal before applying it.");assertEquals(before,f.load().json().toString());ui.click("Refresh saved plan");ui.click("Use fixed time");ui.shown("Fixed time copied. Save alarm to keep it.");assertEquals(before,f.load().json().toString());ui.recreate("Edit alarm");ui.shown("Fixed time copied. Save alarm to keep it.");capture("copied");save();Alarm saved=f.load();assertEquals(6,saved.hour);assertEquals(50,saved.minute);assertEquals(initial.days,saved.days);assertEquals(initial.tone,saved.tone);assertEquals(initial.volume,saved.volume);assertTrue(saved.extraLoud);assertTrue(saved.sunrise);assertFalse(saved.enabled);assertEquals(1,f.schedules);plan(1320,480);ui.launch(saved);assertEquals(6,f.load().hour);assertEquals(50,f.load().minute);ui.click("Use sleep plan");ui.click("Cancel");ui.shown("Edit alarm");save();assertEquals(6,f.load().hour);assertEquals(50,f.load().minute);assertEquals(2,f.schedules);});}
 @Test public void datedDstReviewAndSunriseFallbackCopyPreserveTimeBasisAndDate()throws Exception{run(f->{TimeZone.setDefault(TimeZone.getTimeZone("America/New_York"));f.zone=ZoneId.of("America/New_York");plan(1350,480);Alarm initial=f.load();initial.enabled=false;initial.hour=9;initial.minute=20;initial.date=LocalDate.of(2026,3,8);initial.days.clear();try(Store s=f.open()){s.save(initial);}ui.launch(initial);ui.click("Use sleep plan");ui.shown("The clock changes during this planned interval. Elapsed interval: 7 h.");capture("dated");ui.click("Use fixed time");save();Alarm saved=f.load();assertEquals(initial.date,saved.date);assertTrue(saved.days.isEmpty());assertEquals(6,saved.hour);assertEquals(30,saved.minute);saved.solar=new SunriseSchedule(40.72,-74.02,-30,true);saved.hour=9;saved.minute=20;try(Store s=f.open()){s.save(saved);}String solar=saved.solar.key();ui.launch(saved);ui.click("Use sleep plan");ui.shown("Use as sunrise fallback");capture("sunrise-fallback");ui.click("Use as sunrise fallback");ui.shown("Sunrise fallback copied. Save alarm to keep it.");save();Alarm copy=f.load();assertEquals(solar,copy.solar.key());assertEquals(initial.date,copy.date);assertTrue(copy.days.isEmpty());assertEquals(6,copy.hour);assertEquals(30,copy.minute);assertFalse(copy.enabled);assertEquals(2,f.schedules);});}
}
